fn gcd(m: Int, n: Int) -> Int {
    if n == 0 {
        m
    } else {
        gcd(n, m % n)
    }
}

fn main() {
    print(gcd(105, 252))
}

fn gcd(mut a: u32, mut b: u32) -> u32 {
    while b != 0 {
        let tmp = b;
        b = a % b;
        a = tmp;
    }
    a
}

fn main() {
    let ans = gcd(252, 105);
    println!("{}", ans);
}

